const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');let paused=motionQuery.matches;try{paused=paused||sessionStorage.getItem('lotus-motion')==='paused'}catch{}const motionButton=document.querySelector('.motion');document.documentElement.classList.add('js-motion');function setMotion(){document.documentElement.classList.toggle('paused',paused);motionButton.textContent=paused?'Resume animations':'Pause animations';motionButton.setAttribute('aria-pressed',String(paused));try{sessionStorage.setItem('lotus-motion',paused?'paused':'enabled')}catch{}}setMotion();motionButton.addEventListener('click',()=>{paused=!paused;setMotion()});motionQuery.addEventListener('change',e=>{paused=e.matches;setMotion()});const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));document.querySelectorAll('.practice-grid,.directory-grid').forEach(grid=>[...grid.children].forEach((el,i)=>el.style.setProperty('--delay',`${i*.08}s`)));const sectionLinks=[...document.querySelectorAll('.page-nav a')];let pending=false;function update(){document.querySelector('.reading-progress').style.width=(scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)*100)+'%';let active=null;sectionLinks.forEach(a=>{const section=document.querySelector(a.hash);if(section&&section.getBoundingClientRect().top<innerHeight*.45)active=a;a.removeAttribute('aria-current')});active?.setAttribute('aria-current','location');pending=false}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);update();
// Background animation is decorative, pauseable and only active near the viewport.
const livingSurfaces=document.querySelectorAll('.world-hero,.practice-editorial,.intro,.ritual,.faq,.join,.about-hero,.values,.contact');const surfaceObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('background-resting',!e.isIntersecting)),{rootMargin:'150px'});livingSurfaces.forEach(surface=>{surface.classList.add('living-surface','background-resting');const layer=document.createElement('div');layer.className='living-background';layer.setAttribute('aria-hidden','true');layer.innerHTML='<span class="colour-cloud"></span><span class="colour-cloud cloud-two"></span><span class="colour-cloud cloud-three"></span><span class="silk-lines"></span><span class="light-specks"></span>';surface.prepend(layer);surfaceObserver.observe(surface)});document.addEventListener('visibilitychange',()=>{document.documentElement.classList.toggle('background-resting',document.hidden)});

